#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int num_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        num_threads = omp_get_num_threads();
    }

    std::vector<long long> blockSums(static_cast<std::size_t>(num_threads), 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T = omp_get_num_threads();

        const std::size_t start = (n * static_cast<std::size_t>(tid)) / static_cast<std::size_t>(T);
        const std::size_t end   = (n * static_cast<std::size_t>(tid + 1)) / static_cast<std::size_t>(T);

        long long localSum = 0;
        for (std::size_t i = start; i < end; ++i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }

        blockSums[static_cast<std::size_t>(tid)] = localSum;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += blockSums[static_cast<std::size_t>(t)];
        }

        for (std::size_t i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
        }
    }
}
